const tabs=[...document.querySelectorAll('[data-skill]')];
function selectSkill(button){const data=skills[button.dataset.skill];tabs.forEach(t=>{const active=t===button;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;});document.querySelector('#skill-panel').setAttribute('aria-labelledby',button.id);document.querySelector('.panel-symbol').textContent=data.symbol;document.querySelector('.panel-caption').textContent=data.caption;document.querySelector('#skill-title').textContent=data.title;document.querySelector('#skill-description').textContent=data.description;document.querySelector('#skill-chips').replaceChildren(...data.tags.map(t=>{const e=document.createElement('span');e.textContent=t;return e;}));}
tabs.forEach((button,index)=>{button.addEventListener('click',()=>selectSkill(button));button.addEventListener('keydown',e=>{let next;if(['ArrowDown','ArrowRight'].includes(e.key))next=(index+1)%tabs.length;if(['ArrowUp','ArrowLeft'].includes(e.key))next=(index+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectSkill(tabs[next]);tabs[next].focus();}});});
const responses={help:'Comandos disponibles:\nwhoami — conoce mi perfil\nstack — tecnologías por área\nexperience — trayectoria profesional\neducation — formación y certificaciones\nlanguages — idiomas\ncontact — conectemos\nclear — limpia esta terminal',whoami:'Isaac Alberto Hidalgo Vargas\nIngeniero en Sistemas Computacionales.\nFull Stack / Mobile Developer.\nHeredia, Costa Rica.\nMe enfoco en resolver problemas, aprender continuamente y construir soluciones eficientes y seguras.',stack:Object.values(skills).map(s=>s.title+'\n'+s.tags.join(' · ')).join('\n\n'),experience:'2026 → Actualidad | Wipro, servicios para Citi\nService Desk Analyst: incidentes, accesos, troubleshooting y seguimiento de solicitudes.\n\n2023 → Actualidad | Freelance\nDesarrollo de escritorio, web y móvil; APIs, datos y arquitectura.\n\n2024 → 2025 | Pasantía remunerada\nCiberseguridad y marketing digital; Linux, Python y Bash.',education:'Bachillerato en Ingeniería en Sistemas Computacionales\nUniversidad Fidélitas · marzo 2026\n\nTécnico en Redes y Ciberseguridad\nUniversidad Fundepos · marzo 2025\n\nCertificaciones: NDG Linux Essentials / CyberOps Associate',languages:'Español: nativo\nInglés: avanzado (C1)',contact:'Conversemos sobre desarrollo, automatización o sistemas.\nCorreo: isaacvar05@gmail.com\nEncuentra el enlace de contacto al final de la página.'};
const terminal=document.querySelector('#terminal-output');
function runCommand(value){const command=value.trim().toLowerCase();if(!command)return;if(command==='clear'){terminal.replaceChildren();return;}const line=document.createElement('p');line.className='muted';line.textContent=({whoami:'¿Quién soy?',stack:'Mis tecnologías',experience:'Mi experiencia',contact:'Contactar'})[command] || 'visitante ~ $ '+value.slice(0,150);const answer=document.createElement('p');answer.textContent=responses[command]||'Comando no reconocido. Escribe help para explorar las opciones.';terminal.append(line,answer);while(terminal.children.length>40)terminal.firstElementChild.remove();terminal.scrollTop=terminal.scrollHeight;}
document.querySelector('#terminal-form').addEventListener('submit',e=>{e.preventDefault();const input=document.querySelector('#command');runCommand(input.value);input.value='';});document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>runCommand(b.dataset.command)));
const pipelineButton=document.querySelector('#pipeline-run');let pipelineTimers=[];pipelineButton.addEventListener('click',()=>{pipelineTimers.forEach(clearTimeout);const steps=[...document.querySelectorAll('#pipeline-stages li')];steps.forEach(s=>s.classList.remove('active'));pipelineButton.disabled=true;const messages=['01 / LA INTERFAZ ENVÍA LA SOLICITUD','02 / LA API VALIDA Y PROCESA','03 / LA BASE DE DATOS DEVUELVE EL RESULTADO','04 / LA INTERFAZ PRESENTA LA RESPUESTA'];steps.forEach((step,i)=>pipelineTimers.push(setTimeout(()=>{step.classList.add('active');document.querySelector('#pipeline-status').textContent=messages[i];},i*700)));pipelineTimers.push(setTimeout(()=>{document.querySelector('#pipeline-status').textContent='200 OK / RECORRIDO COMPLETO · SIMULACIÓN LOCAL';pipelineButton.disabled=false;},2900));});
