function updateClock(){document.querySelector('#clock').textContent=new Intl.DateTimeFormat('es-CR',{timeZone:'America/Costa_Rica',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' CST';}updateClock();setInterval(updateClock,60000);document.querySelector('#year').textContent=new Date().getFullYear();
